"""Generate an S6 all-data stage (nartaa's S6fall recipe, discussion 749359) from heliosli_compact_stage.py.

The heliosli stage runs compact_infer.py on a bundle described by heliosli/rsna-knee-compact-v1's manifest. Here the manifest
is inline (nartaa's inference geometry: rsna-knee-s6fall-solo B_GEOMETRY) and the bundle is assembled at runtime from the
checkpoints' own datasets (sha256-checked; nothing re-hosted). compact_infer averages every <arm>_s*_f*.pt in the bundle.

  python submission/external/make_s6_stage.py s42 nartaa/rsna-knee-s6fall-weights:E_prior_s42_fall.pt:<sha256> [...]
  -> submission/external/s6_stage_s42.py  (use with build_kernels.py --ext-hel2-script s6_stage_s42.py)"""
import json, sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ANATOMY_SHA = "5904dd16eb9a4fd7a1caf90ac977f8fe2ef364908598c23c209db3fe7fd1563e"

OLD_ASSETS = """M_SRC = find_mount(C_SLUG, 'manifest.json')
manifest = json.loads((M_SRC / 'manifest.json').read_text())
assert manifest['bundle_id'] == BUNDLE_ID, (manifest['bundle_id'], BUNDLE_ID)
for name in manifest['models'] + (manifest.get('models2') or []):
    assert hashlib.sha256((M_SRC / name).read_bytes()).hexdigest() == manifest['sha256'][name], name
    shutil.copy(M_SRC / name, BUNDLE / name)
"""


def main():
    name, specs = sys.argv[1], sys.argv[2:]
    models = []
    for s in specs:
        slug, fname, digest = s.split(":")
        models.append([slug.split("/")[-1], fname, digest])
    manifest = {"bundle_id": "s6fall_" + name, "arm": "E_prior", "models": [m[1] for m in models], "backbone": "convnext_small",
                "size": 320, "crop": 288, "eval_stride": 1, "views": "v4", "slices": 3, "phys_mm": 3.5,
                "anchor_weights_sha256": ANATOMY_SHA, "state_spec": None, "side_model": None, "models2": None}
    new_assets = ("# [s6] bundle assembled from the checkpoints' own datasets (nartaa S6fall geometry; make_s6_stage.py)\n"
                  "S6_MODELS = %s\n" % json.dumps(models) +
                  "manifest = %s\n" % json.dumps(manifest) +
                  "M_SRC = None\n"
                  "for _slug, _name, _digest in S6_MODELS:\n"
                  "    _src = find_mount(_slug, _name)\n"
                  "    assert hashlib.sha256((_src / _name).read_bytes()).hexdigest() == _digest, _name\n"
                  "    shutil.copy(_src / _name, BUNDLE / _name)\n")
    src = (HERE / "heliosli_compact_stage.py").read_text(encoding="utf-8")
    reps = [(OLD_ASSETS, new_assets),
            ("ARM = 'E_lrprior'\n", "ARM = 'E_prior'\n"),
            ("BUNDLE_ID = '209a32c8b50a6b1c'\n", "BUNDLE_ID = 's6fall_%s'\n" % name),
            ('"""External stage: heliosli\'s compact ConvNeXt-S model',
             '"""[s6, generated by make_s6_stage.py: S6fall ConvNeXt-S checkpoints %s, nartaa geometry 320/288 stride 1]\n'
             'External stage: heliosli\'s compact ConvNeXt-S model' % [m[1] for m in models])]
    for old, new in reps:
        assert src.count(old) == 1, ("expected exactly one match", old[:60])
        src = src.replace(old, new)
    out = HERE / ("s6_stage_%s.py" % name)
    out.write_text(src, encoding="utf-8")
    print("wrote", out)


if __name__ == "__main__":
    main()
